private val cache = HashMap<String, ImageVector>()

/** Null for Uncategorized: the row shows the merchant's initial instead. */
fun categoryIcon(category: String?): ImageVector? {
    val d = PATHS[category ?: return null] ?: return null
    return cache.getOrPut(category) {
        ImageVector.Builder(category, 24.dp, 24.dp, 960f, 960f).apply {
            // Symbols use a 0,-960 origin; shift it back into the viewport.
            group(translationY = 960f) { addPath(addPathNodes(d), fill = SolidColor(Color.Black)) }
        }.build()
    }
}
